import{_ as e,H as d,f as o,i as r}from"./chunks/framework.CBmkDW73.js";const m=JSON.parse('{"title":"仕様レビュアーゲート (Spec Reviewers)","description":"","frontmatter":{},"headers":[],"relativePath":"ja/skills/reviewers.md","filePath":"ja/skills/reviewers.md"}'),c={name:"ja/skills/reviewers.md"};function a(s,t,i,n,l,p){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="仕様レビュアーゲート-spec-reviewers" tabindex="-1">仕様レビュアーゲート (Spec Reviewers) <a class="header-anchor" href="#仕様レビュアーゲート-spec-reviewers" aria-label="Permalink to &quot;仕様レビュアーゲート (Spec Reviewers)&quot;">​</a></h1><p>仕様レビュアープロトコル（<code>skills/references/reviewers.md</code>）は、<code>design</code> 段階でステージング仕様をディスクに保存した後、<code>plan</code> に渡す前に実行される並列レビューゲートを規定します。</p><h2 id="トリガーベースの動的選択" tabindex="-1">トリガーベースの動的選択 <a class="header-anchor" href="#トリガーベースの動的選択" aria-label="Permalink to &quot;トリガーベースの動的選択&quot;">​</a></h2><p>仕様の条件に一致するすべてのレビュアーを起動します。条件は加算式であり、ベースラインのトリガー 1 のみが一致する場合は <code>spec-compliance</code> のみ実行されます。</p><table tabindex="0"><thead><tr><th>#</th><th>トリガー条件</th><th>起動されるレビュアー</th><th>モデル階層</th><th>検査役割</th></tr></thead><tbody><tr><td>1</td><td><strong>常時</strong>（ベースライン）</td><td><code>spec-compliance</code></td><td><code>balanced</code></td><td>各 <code>contract:</code>/<code>invariant:</code> に対応する受入 <code>test:</code> があり、失敗モード・スコープ境界・データ形状が具体的であることを検証。</td></tr><tr><td>2</td><td><strong>≥3 個の状態列挙または状態マシン</strong>を定義</td><td><code>state-machine</code></td><td><code>strongest</code></td><td>すべての正当な状態遷移を列挙し、欠落エッジ・デッド/到達不能状態・未宣言の初期/終了状態を指摘。</td></tr><tr><td>3</td><td><strong>同一動作を相互参照する ≥2 個のルール</strong>を含む</td><td><code>consistency</code></td><td><code>strongest</code></td><td>矛盾、優先順位の未定義、不完全な例外リスト、本文と表の不一致を検出。</td></tr><tr><td>4</td><td><strong><code>topology=multi-module</code> または共有契約の宣言</strong></td><td><code>boundary</code></td><td><code>balanced</code></td><td>共有契約の単一所有者、明示的バージョニング、シリアライズ互換性、モジュール横断前提を検証。</td></tr><tr><td>5</td><td><strong>永続書き込み・外部副作用・コミット意味論</strong>を含む</td><td><code>safety</code></td><td><code>strongest</code></td><td>各書き込みパスを追跡し、クラッシュ復旧漏れ、重複書き込み、部分コミット、原子性境界を検証。</td></tr><tr><td>6</td><td><strong><code>scope=complex</code> またはサブエージェント並列実装を予定</strong></td><td><code>implementability</code></td><td><code>balanced</code></td><td>初見の実装者視点で読み、未定義データ構造、曖昧な順序、エラー処理・デフォルト値の欠落を指摘。</td></tr></tbody></table><p>モデル階層の解決順序: プロジェクト <code>.praxis/model-tiers.yaml</code> → ユーザー <code>~/.praxis/model-tiers.yaml</code> → ハーネスのデフォルトモデル（<code>tiers.&lt;tier&gt;.model</code> を参照）。</p><h2 id="並行実行と-coordinator-の統合評価" tabindex="-1">並行実行と Coordinator の統合評価 <a class="header-anchor" href="#並行実行と-coordinator-の統合評価" aria-label="Permalink to &quot;並行実行と Coordinator の統合評価&quot;">​</a></h2><ol><li><strong>並行起動</strong>: トリガーされたすべてのレビュアーは独立したサブエージェントとして仕様書パス（<code>docs/staging/specs/YYYY-MM-DD-&lt;topic&gt;.md</code>）のみを受け取り、1行1件（<code>BLOCK | GAP | CONFLICT</code>）で返却します。</li><li><strong>Coordinator の統合評価</strong>: 1回のみ実行されます。主エージェントが指摘を批判的に評価し、矛盾の解決、漏れの発見、深刻度判定（<code>BLOCK</code> または理由付きの <code>DEFER</code>）を行い、一度の編集で仕様書を修正してユーザーへ報告します。レビュアーは助言し、Coordinator が決定します。</li></ol>',8)])])}const g=e(c,[["render",a]]);export{m as __pageData,g as default};
